import { Component, createMemo, For, onCleanup, onMount, ParentComponent, Show, splitProps, untrack } from "solid-js";

import { DisplayQueueManager } from "#core/ui/context-manager/display-queue-manager.js";
import { InputEngineEventName, NavigateInputEventName, type InputEngineEvent } from "#core/ui/input/input-support.js";
import { InterfaceMode } from "#core/ui/interface-modes/interface-modes.js";
import { Button } from "#core/ui-next/components/button.jsx";
import { CardFrame } from "#core/ui-next/components/card-frame.jsx";
import { defineLegacyComponent } from "#core/ui-next/components/fxs-solid-component.js";
import { L10n } from "#core/ui-next/components/l10n.jsx";
import { HSlot } from "#core/ui-next/components/slot.jsx";
import { Tab } from "#core/ui-next/components/tab.jsx";
import { Tooltip, TooltipHorizontalPosition, TooltipVerticalPosition } from "#core/ui-next/components/tooltip.jsx";
import { useAudio } from "#core/ui-next/services/audio-support.js";
import { ComponentRegistry } from "#core/ui-next/services/component-registry.js";
import { LayoutModel, useIsSmallScreen } from "#core/ui-next/utilities/layout-utilities.js";

import TutorialManager from "#base/ui/tutorial/tutorial-manager.js";
import { ScreenFrame } from "#base/ui-next/components/screen-frame.jsx";
import { CultureVictoryTab } from "#base/ui-next/screens/victories/culture-victory-tab.jsx";
import { EconomicVictoryTab } from "#base/ui-next/screens/victories/economic-victory-tab.jsx";
import { MilitaryVictoryTab } from "#base/ui-next/screens/victories/military-victory-tab.jsx";
import { ScienceVictoryTab } from "#base/ui-next/screens/victories/science-victory-tab.jsx";
import { ScoreVictoryTab } from "#base/ui-next/screens/victories/score-victory-tab.jsx";
import { VictoriesSummary } from "#base/ui-next/screens/victories/summary-victory-tab.jsx";
import {
	createVictoriesScreenModel,
	MilitaryStructureDetail,
	VictoriesScreenContext,
} from "#base/ui-next/screens/victories/victories-screen-model.js";

import style from "#base/ui-next/screens/victories/victories-screen.scss?url";

interface VictoriesScreenProps {
	ref?: HTMLDivElement | ((el: HTMLDivElement) => void);
	endGameScreen?: boolean;
	allowOneMoreTurn?: boolean;
	showNextTurnButton?: boolean;
	activeTabId?: () => string;
	onCancelInput?: () => void;
}

//#region SCREEN LAYOUT
const VictoriesScreenComponent: Component<VictoriesScreenProps> = (props) => {
	const isSmallScreen = useIsSmallScreen();
	const endGameScreen = untrack(() => props.endGameScreen);
	const allowOneMoreTurn = untrack(() => props.allowOneMoreTurn);
	const showNextTurnButton = untrack(() => props.showNextTurnButton);
	const model = createVictoriesScreenModel(endGameScreen, allowOneMoreTurn, showNextTurnButton);
	const defaultTab = createMemo(() => {
		return props.activeTabId?.() ?? undefined;
	});

	const audio = useAudio("VictoryScreen");

	onMount(() => {
		audio("popup-open");
		window.addEventListener(InputEngineEventName, handleWindowEngineInput);
		window.addEventListener(NavigateInputEventName, handleWindowEngineInput);
	});

	onCleanup(() => {
		window.removeEventListener(InputEngineEventName, handleWindowEngineInput);
		window.removeEventListener(NavigateInputEventName, handleWindowEngineInput);
	});

	const handleOnClosing = () => {
		if (!props.endGameScreen) {
			audio("popup-close");
			//this second trigger is independent and is used to cancel the victory sounds
			audio("stop-sound");
		}
	};

	const handleWindowEngineInput = (inputEvent: InputEngineEvent) => {
		if (inputEvent.detail.status == InputActionStatuses.FINISH) {
			switch (inputEvent.detail.name) {
				case "shell-action-1":
					model.onGamepadInspectButton();
					inputEvent.preventDefault();
					inputEvent.stopImmediatePropagation();
					break;

				case "shell-action-3":
					if (!TutorialManager.isShowing()) {
						model.onGamepadInfoButton();
					}
					break;

				case "sys-menu":
				case "accept":
					if (props.endGameScreen) {
						inputEvent.preventDefault();
						inputEvent.stopImmediatePropagation();
					}
					break;
			}
		}
	};

	const justOneMoreTurn = () => {
		const args = {};
		const result = Game.PlayerOperations.canStart(
			GameContext.localPlayerID,
			PlayerOperationTypes.EXTEND_GAME,
			args,
			false,
		);
		if (result.Success) {
			Game.PlayerOperations.sendRequest(GameContext.localPlayerID, PlayerOperationTypes.EXTEND_GAME, args);
			DisplayQueueManager.closeMatching("EndgameScreen");
			InterfaceMode.switchToDefault();
		}
	};

	const advanceToNextPlayer = () => {
		GameContext.sendTurnComplete();
		DisplayQueueManager.closeMatching("EndgameScreen");
		InterfaceMode.switchToDefault();
	};

	return (
		<VictoriesScreenContext.Provider value={model}>
			<ScreenFrame
				name="Victories-Screen"
				panelContext="screen-victory-progress"
				audioContext="VictoryScreen"
				title="LOC_UI_VICTORY_PROGRESS"
				ornatePanelData={model.data.ornatePanelData}
				onClosing={handleOnClosing}
				hideClose={props.endGameScreen}
				addYieldBar={false}
			>
				<Tab
					class="victories-tab-bar w-full flex flex-col flex-auto pointer-events-auto mx-5"
					defaultTab={defaultTab() ? defaultTab() : model.data.defaultTab}
					onTabChanged={(tabProps) => {
						if (tabProps) {
							if (model.tabChanged(tabProps.name)) {
								if (tabProps.name !== "summary" && tabProps.name !== "score") {
									useAudio("TabListItem")(`tab-nav-${tabProps.name}`);
								}
							}
						}
					}}
				>
					<Tab.TabList
						class="victories-tab-width self-center text-base font-base"
						nextHotkey="nav-next"
						previousHotkey="nav-previous"
						titleClass={`${LayoutModel.get().screenWidthDownScaled() < 1600 ? "text-2xs ml-2" : `${LayoutModel.get().screenWidthDownScaled() <= 1920 ? "text-xs ml-2" : ""}`}`}
					/>
					<div
						class={`${isSmallScreen() ? "mt-2" : "mt-8"} flex flex-col flex-auto bg-accent-6 items-center mb-5 pl-8 pr-8 pt-8 relative victories-panel-container`}
					>
						<div class="absolute inset-0 bottom-0 filigree-inner-frame-top" />
						<div class="absolute inset-0 bottom-0 filigree-inner-frame-bottom" />
						<Tab.Output />
					</div>
					<Tab.Item
						name="summary"
						title={() => "LOC_PEDIA_PAGE_CHAPTER_SUMMARY_TITLE"}
						body={() => <VictoriesSummary />}
					/>
					<Tab.Item
						name="cultural"
						title={() => "LOC_VICTORY_CULTURE_MODERN_NAME"}
						disabled={!Game.VictoryManager.isCountdownVictoryEnabled(Database.makeHash("VICTORY_CULTURE_MODERN"))}
						body={() => <CultureVictoryTab {...model.data.cultureDetails} />}
					/>
					<Tab.Item
						name="economic"
						title={() => "LOC_VICTORY_ECONOMIC_MODERN_NAME"}
						disabled={!Game.VictoryManager.isCountdownVictoryEnabled(Database.makeHash("VICTORY_ECONOMIC_MODERN"))}
						body={() => <EconomicVictoryTab />}
					/>
					<Tab.Item
						name="military"
						title={() => "LOC_VICTORY_MILITARY_MODERN_NAME"}
						disabled={!Game.VictoryManager.isCountdownVictoryEnabled(Database.makeHash("VICTORY_MILITARY_MODERN"))}
						body={() => <MilitaryVictoryTab />}
					/>
					<Tab.Item
						name="scientific"
						title={() => "LOC_VICTORY_SCIENCE_MODERN_NAME"}
						disabled={!Game.VictoryManager.isCountdownVictoryEnabled(Database.makeHash("VICTORY_SCIENCE_MODERN"))}
						body={() => <ScienceVictoryTab {...model.data.scienceDetails} />}
					/>
					<Tab.Item
						name="score"
						title={() => "LOC_VICTORY_SCORE_NAME"}
						disabled={!Game.VictoryManager.isScoreVictoryEnabled()}
						body={() => <ScoreVictoryTab />}
					/>
				</Tab>
				<Show when={props.endGameScreen}>
					<div class="absolute bottom-10 right-10 flex flow-row">
						<Show when={props.allowOneMoreTurn}>
							<Button
								onActivate={() => {
									justOneMoreTurn();
								}}
								hotkeyAction="nav-shell-previous"
								navTrayText="LOC_END_GAME_CONTINUE"
								class="mr-8"
							>
								<L10n.Compose text="LOC_END_GAME_CONTINUE" />
							</Button>
						</Show>

						<Show when={!props.showNextTurnButton}>
							<Button
								onActivate={() => {
									engine.call("exitToMainMenu"); // Return to Main Menu
								}}
								hotkeyAction="nav-shell-next"
								navTrayText="LOC_END_GAME_EXIT"
							>
								<L10n.Compose text="LOC_END_GAME_EXIT" />
							</Button>
						</Show>
						<Show when={props.showNextTurnButton}>
							<Button
								onActivate={() => {
									advanceToNextPlayer();
								}}
								hotkeyAction="nav-shell-next"
								navTrayText="LOC_ACTION_PANEL_NEXT_TURN"
							>
								<L10n.Compose text="LOC_ACTION_PANEL_NEXT_TURN" />
							</Button>
						</Show>
					</div>
				</Show>
			</ScreenFrame>
		</VictoriesScreenContext.Provider>
	);
};
//#endregion

//region MILITARY TOOLTIP
export const MilitaryTooltip: ParentComponent<MilitaryStructureDetail> = (props) => {
	const [local, _other] = splitProps(props, ["children"]);

	return (
		<Tooltip
			initialHPosition={TooltipHorizontalPosition.RIGHT}
			initialVPosition={TooltipVerticalPosition.CENTER}
		>
			<Tooltip.Trigger>{local.children}</Tooltip.Trigger>
			<Tooltip.Content>
				<Tooltip.Frame>
					<div class="items-center">
						<div class="font-title-base fxs-header uppercase self-center mb-4">
							<L10n.Compose text={props.hasMet ? props.name : "LOC_LEADER_UNMET_NAME"} />
						</div>
						<CardFrame class="mb-4">
							<For each={props.breakdown}>
								{(breakdown) => (
									<HSlot class="mx-3 my-2 justify-between font-body text-sm text-white ml-4">
										<div>
											<L10n.Compose text={breakdown.name} />
										</div>
										<div class="ml-8">{Locale.toNumber(breakdown.points)}</div>
									</HSlot>
								)}
							</For>
						</CardFrame>
						<Show when={props.breakdown.length > 1}>
							<CardFrame>
								<HSlot class="mx-3 my-2 justify-between">
									<div class="font-title-sm uppercase fxs-header">
										<L10n.Compose text="LOC_VICTORIES_TOOLTIP_TOTAL" />
									</div>
									<div class="ml-12 font-body text-sm text-white">
										{Locale.toNumber(props.points)}
									</div>
								</HSlot>
							</CardFrame>
						</Show>
					</div>
				</Tooltip.Frame>
			</Tooltip.Content>
		</Tooltip>
	);
};
//#endregion

export const VictoriesScreen = ComponentRegistry.register({
	name: "VictoriesScreen",
	styles: [style],
	createInstance: VictoriesScreenComponent,
});

defineLegacyComponent(
	"screen-victory-progress",
	{
		classNames: ["fullscreen"],
		attrs: {
			endGameScreen: "false",
			activeTabId: "",
			allowOneMoreTurn: "true",
			showNextTurnButton: "false",
		},
	},
	(attrs) => {
		Input.setActiveContext(InputContext.Shell);
		const endGameFlag = attrs["endGameScreen"] == "true" ? true : false;
		const activeTabeId = attrs["activeTabId"] || "";
		const allowOneMoreTurn = attrs["allowOneMoreTurn"] == "true" ? true : false;
		const showNextTurnButton = attrs["showNextTurnButton"] == "true" ? true : false;
		return (
			<VictoriesScreen
				endGameScreen={endGameFlag}
				allowOneMoreTurn={allowOneMoreTurn}
				showNextTurnButton={showNextTurnButton}
				activeTabId={() => activeTabeId}
			/>
		);
	},
);
